<?php
require_once __DIR__ . '/../includes/auth.php';
wajibAdminArea();
require_once __DIR__ . '/../config/database.php';
$jenis = ($_GET['jenis'] ?? 'pembayaran') === 'keluhan' ? 'keluhan' : 'pembayaran';
$mulai = trim($_GET['mulai'] ?? date('Y-m-01'));
$sampai = trim($_GET['sampai'] ?? date('Y-m-d'));
$cari = trim($_GET['cari'] ?? '');
$params = ['mulai'=>$mulai, 'sampai'=>$sampai];
if ($jenis === 'pembayaran') {
 $sql = "SELECT b.tanggal_pembayaran AS tanggal,b.periode_sewa AS rincian,p.nama,k.nomor_kamar,b.jumlah_pembayaran AS nilai,b.status_pembayaran AS status FROM pembayaran b JOIN penghuni p ON p.id_penghuni=b.id_penghuni LEFT JOIN kamar k ON k.id_kamar=p.id_kamar WHERE COALESCE(b.tanggal_pembayaran, CONCAT(LEFT(b.periode_sewa,7),'-01')) BETWEEN :mulai AND :sampai";
 if($cari!==''){$sql.=" AND (p.nama LIKE :cari_nama OR b.periode_sewa LIKE :cari_periode OR k.nomor_kamar LIKE :cari_kamar)";$params['cari_nama']=$params['cari_periode']=$params['cari_kamar']='%'.$cari.'%';}
 $sql.=" ORDER BY tanggal DESC, p.nama ASC";
} else {
 $sql="SELECT k.tanggal_keluhan AS tanggal,k.kategori_keluhan AS rincian,p.nama,kamar.nomor_kamar, k.isi_keluhan AS nilai,k.status_penanganan AS status FROM keluhan k JOIN penghuni p ON p.id_penghuni=k.id_penghuni LEFT JOIN kamar ON kamar.id_kamar=p.id_kamar WHERE k.tanggal_keluhan BETWEEN :mulai AND :sampai";
 if($cari!==''){$sql.=" AND (p.nama LIKE :cari_nama OR k.isi_keluhan LIKE :cari_isi OR k.status_penanganan LIKE :cari_status)";$params['cari_nama']=$params['cari_isi']=$params['cari_status']='%'.$cari.'%';}
 $sql.=" ORDER BY k.tanggal_keluhan DESC,p.nama ASC";
}
$st=$pdo->prepare($sql);$st->execute($params);$data=$st->fetchAll();
if(isset($_GET['export']) && $_GET['export']==='csv') { header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="laporan_'.$jenis.'_'.date('Ymd').'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Tanggal','Penghuni','Kamar','Periode/Kategori','Nilai/Isi','Status']);foreach($data as $r)fputcsv($out,[$r['tanggal'],$r['nama'],$r['nomor_kamar'],$r['rincian'],$r['nilai'],$r['status']]);fclose($out);exit;}
function eLap($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function tLap($v){return $v?date('d-m-Y',strtotime($v)):'-';}
$total=0;$lunas=0;$belum=0;foreach($data as $r){if($jenis==='pembayaran'){$total+=(float)$r['nilai'];if($r['status']==='lunas')$lunas+=(float)$r['nilai'];else $belum+=(float)$r['nilai'];}}
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Laporan | KosSpace</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="../assets/css/app.css" rel="stylesheet"><style>@media print{.sidebar,.topbar,.no-print,.app-footer{display:none!important}.app-main{padding:0!important;margin:0!important}.panel{box-shadow:none!important;border:0!important}}</style></head><body><div class="app-shell d-flex"><?php include __DIR__.'/../includes/admin_sidebar.php';?><main class="app-main"><header class="topbar"><div><div class="topbar-kicker">Analisis dan laporan</div><div class="topbar-title">Laporan operasional</div></div><div class="user-chip"><span><?=eLap($_SESSION['nama']??'Pengguna')?></span><a href="../logout.php" class="btn btn-outline-secondary ms-2"><i class="bi bi-box-arrow-right"></i></a></div></header><section class="page-heading"><div><div class="eyebrow">Pelaporan</div><h1>Laporan <?= $jenis==='pembayaran'?'Pembayaran':'Keluhan' ?></h1><p>Gunakan rentang tanggal, pencarian, dan ekspor untuk evaluasi operasional kos.</p></div></section><section class="panel"><form method="get" class="row g-2 align-items-end no-print"><div class="col-md-3"><label class="form-label">Jenis laporan</label><select name="jenis" class="form-select"><option value="pembayaran" <?=$jenis==='pembayaran'?'selected':''?>>Pembayaran</option><option value="keluhan" <?=$jenis==='keluhan'?'selected':''?>>Keluhan</option></select></div><div class="col-md-2"><label class="form-label">Dari tanggal</label><input type="date" name="mulai" value="<?=eLap($mulai)?>" class="form-control" required></div><div class="col-md-2"><label class="form-label">Sampai tanggal</label><input type="date" name="sampai" value="<?=eLap($sampai)?>" class="form-control" required></div><div class="col-md-3"><label class="form-label">Cari</label><input name="cari" value="<?=eLap($cari)?>" class="form-control" placeholder="Nama, kamar, isi..."></div><div class="col-md-2 d-flex gap-2"><button class="btn btn-primary"><i class="bi bi-search"></i></button><a class="btn btn-outline-secondary" href="laporan.php">Reset</a></div><div class="col-12 d-flex gap-2 mt-3"><a class="btn btn-outline-success" href="?<?=http_build_query(array_merge($_GET,['export'=>'csv']))?>"><i class="bi bi-file-earmark-spreadsheet me-1"></i>Ekspor CSV</a><button type="button" class="btn btn-outline-secondary" onclick="window.print()"><i class="bi bi-printer me-1"></i>Cetak / PDF</button></div></form><hr class="no-print"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="panel-title mb-0">Hasil laporan</h2><span class="text-secondary small"><?=count($data)?> data</span></div><?php if($jenis==='pembayaran'):?><div class="row g-3 mb-4"><div class="col-md-4"><div class="stat-card"><div class="stat-label">Total nilai tagihan</div><div class="stat-value fs-4">Rp <?=number_format($total,0,',','.')?></div></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">Nilai lunas</div><div class="stat-value fs-4">Rp <?=number_format($lunas,0,',','.')?></div></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">Nilai belum lunas</div><div class="stat-value fs-4">Rp <?=number_format($belum,0,',','.')?></div></div></div></div><?php endif;?><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Tanggal</th><th>Penghuni</th><th>Kamar</th><th><?= $jenis==='pembayaran'?'Periode':'Kategori' ?></th><th><?= $jenis==='pembayaran'?'Jumlah':'Isi keluhan' ?></th><th>Status</th></tr></thead><tbody><?php if(!$data):?><tr><td colspan="6" class="text-center text-secondary py-4">Tidak ada data pada rentang yang dipilih.</td></tr><?php else:foreach($data as $r):?><tr><td><?=tLap($r['tanggal'])?></td><td><?=eLap($r['nama'])?></td><td><?=eLap($r['nomor_kamar']??'-')?></td><td><?=eLap($r['rincian'])?></td><td><?php if($jenis==='pembayaran'):?>Rp <?=number_format((float)$r['nilai'],0,',','.')?><?php else:?><?=eLap($r['nilai'])?><?php endif;?></td><td><?=eLap(ucwords(str_replace('_',' ',$r['status'])))?></td></tr><?php endforeach;endif;?></tbody></table></div></section><footer class="app-footer">&copy; <?=date('Y')?> KosSpace · Sistem Informasi Pengelolaan Kos Mahasiswa</footer></main></div></body></html>
